import { bigint, timestamp as pgTimestamp, uuid } from "drizzle-orm/pg-core";

import { TIMESTAMPTZ_CONFIG } from "./consts";

//// Ids ////

export const id = bigint("id", { mode: "bigint" }).primaryKey();

export const randomId = uuid("id").primaryKey();

//// Timestamps ////

export const timestamp = pgTimestamp("timestamp", TIMESTAMPTZ_CONFIG).notNull();

export const createdAt = pgTimestamp(
  "created_at",
  TIMESTAMPTZ_CONFIG
).notNull();

export const updatedAt = pgTimestamp("updated_at", TIMESTAMPTZ_CONFIG);

export const archivedAt = pgTimestamp("archived_at", TIMESTAMPTZ_CONFIG)
  .notNull()
  .defaultNow();

import { eq } from "drizzle-orm";
import type {
  PreparedQueryConfig,
  PgPreparedQuery,
  PgTable,
  PgColumn,
} from "drizzle-orm/pg-core";
import * as v from "valibot";

import { db } from "@/modules/core/index";
import type { QueryExecutor, Tx } from "@/modules/core/helpers/types";

type StmtParams = [qx: QueryExecutor, label?: string];

/**
 * Convenience function to reduce boilerplate for writing prepared statements.
 *
 * THIS DOES NOT RETURN A STATEMENT DIRECTLY. It returns a function that returns a statement.
 *
 * This allows a single definition for the statement to be run on the database normally OR as part of a transaction.
 *
 * Useful for enforcing the shape of stmt functions used as params for {@link createQueryFn}
 */
export function createStmtFn<T extends PgPreparedQuery<PreparedQueryConfig>>(
  fn: (...[qx, label]: StmtParams) => T
) {
  return (...[qx, label = "default"]: StmtParams) => fn(qx, label);
}

type GenericValidationError = v.ErrorMessage<v.BaseIssue<unknown>> | undefined;

type GenericObjectValidationSchema = v.ObjectSchema<
  v.ObjectEntries,
  GenericValidationError
>;

/**
 * Convenience function to reduce boilerplate for writing functions that query the database.
 *
 * The function returned automatically handles typing for the input based on the validation schema and using a transaction if one is provided.
 */
export function createQueryFn<
  VSchema extends
    | GenericObjectValidationSchema
    | v.VariantSchema<
        string,
        GenericObjectValidationSchema[],
        GenericValidationError
      >,
  Stmt extends PgPreparedQuery<PreparedQueryConfig>,
>({
  vSchema,
  stmtFn,
  defaultStmt,
}: {
  vSchema: VSchema;
  stmtFn: ReturnType<typeof createStmtFn<Stmt>>;
  defaultStmt?: ReturnType<ReturnType<typeof createStmtFn<Stmt>>>;
}) {
  return async (
    input: v.InferInput<typeof vSchema>,
    viaTx?: { tx: Tx; label: string }
  ) => {
    const stmt = viaTx
      ? stmtFn(viaTx.tx, viaTx.label)
      : (defaultStmt ?? stmtFn(db));

    const data = await stmt.execute(v.parse(vSchema, input));

    return data as Awaited<ReturnType<Stmt["execute"]>>;
  };
}

/**
 * Convenience function to reduce boilerplate for writing functions that archives rows for a given table
 *
 * Creates a transaction that confirms the row(s) exists, appends the existing data to an archive table, processes given cascades, and finally removes the row(s)
 *
 * The function returned automatically handles typing for the input based on the select function provided and
 * can extend an external transaction to the query if necessary
 */
export function createArchiveFn<T extends Record<string, string | bigint>>({
  selectFn,
  activeTable,
  archiveTable,
  selectBy = "id",
  cascades,
}: {
  selectFn: (input: T, viaTx?: { tx: Tx; label: string }) => Promise<unknown>;
  activeTable: PgTable & Record<keyof T, PgColumn>;
  archiveTable: PgTable;
  selectBy?: keyof T;
  cascades?: (tx: Tx, selector: T[keyof T]) => Promise<unknown>[];
}) {
  return (input: Parameters<typeof selectFn>[0], externalTx?: Tx) => {
    const _archive = async (tx: Tx) => {
      // Find the existing row data
      const rowData = (await selectFn(input, {
        tx,
        label: "archive",
      })) as Record<string, unknown>[];

      // Throw an error if data isn't found
      if (!rowData.length)
        throw new Error(
          `ARCHIVE ERROR: CANNOT FIND ROW WHERE ${String(selectBy)} = ${input[selectBy]}`
        );

      const selector = input[selectBy];

      // Insert the data into the archive table
      await tx
        .insert(archiveTable)
        .values(rowData.map((row) => ({ ...row, [selectBy]: selector })));

      // Process cascades concurrently
      if (cascades) await Promise.all(cascades(tx, selector));

      // Delete the row data from the active table
      await tx.delete(activeTable).where(eq(activeTable[selectBy], selector));
    };

    // Process with an external transaction if it exists
    if (externalTx) return _archive(externalTx);

    // Process with a newly generated transaction
    return db.transaction((tx) => _archive(tx));
  };
}

import type { db } from "@/modules/core/index";

/** Drizzle Postgres Transaction objecct type alias for convenience */
export type Tx = Parameters<Parameters<typeof db.transaction>[0]>[0];

/** Reference for running a query with the normal db object or a transaction object */
export type QueryExecutor = typeof db | Tx;

import { createArchiveFn } from "@/modules/core/helpers/funcs";

import * as queries from "@/modules/core/models/activities/queries";
import {
  activities,
  activitiesArchive,
} from "@/modules/core/models/activities/schemas";

/** Adds given id to the activitiesArchive, handles related cascades, and removes it from activities */
export const archive = createArchiveFn({
  selectFn: queries.select,
  activeTable: activities,
  archiveTable: activitiesArchive,
});

import { eq, getTableColumns, sql } from "drizzle-orm";

import { createQueryFn, createStmtFn } from "@/modules/core/helpers/funcs";

import { activities } from "@/modules/core/models/activities/schemas";
import * as V from "@/modules/core/models/activities/validations";

//// PRIMITIVES ////

const {
  id,
  failureCause,
  label: labelCol,
  meta,
  success,
  userId,
  usersArchiveId,
  timestamp,
} = getTableColumns(activities);

//// INSERT ////

const insertStmt = createStmtFn((qx, label = "") =>
  qx
    .insert(activities)
    .values({
      userId: sql.placeholder("userId"),
      success: sql.placeholder("success"),
      label: sql.placeholder("label"),
      failureCause: sql.placeholder("failureCause"),
      meta: sql.placeholder("meta"),
    })
    .returning({ id })
    .prepare(`activity_insert_${label}`)
);

export const insert = createQueryFn({ vSchema: V.Insert, stmtFn: insertStmt });

//// SELECT ////

const selectStmt = createStmtFn((qx, label) =>
  qx
    .select({
      failureCause,
      label: labelCol,
      meta,
      success,
      userId,
      usersArchiveId,
      timestamp,
    })
    .from(activities)
    .where(eq(id, sql.placeholder("id")))
    .limit(1)
    .prepare(`activity_select_${label}`)
);

export const select = createQueryFn({ vSchema: V.Select, stmtFn: selectStmt });

import {
  boolean,
  index,
  jsonb,
  pgTable,
  text,
  uuid,
} from "drizzle-orm/pg-core";

import { id, timestamp, archivedAt } from "@/modules/core/helpers/cols";
import { users, usersArchive } from "@/modules/core/models/users/schemas";

const activitiesBaseCols = {
  userId: uuid("user_id").references(() => users.id),
  usersArchiveId: uuid("users_archive_id").references(() => usersArchive.id),
  label: text("label").notNull(), // Could be an enum, but it gets difficult to manage as ops are added
  success: boolean("success").notNull(),
  failureCause: text("failure_cause"), // Could be an enum, but it gets difficult to manage as ops are added
  meta: jsonb("meta"),
};

export const activities = pgTable(
  "activities",
  {
    ...activitiesBaseCols,
    id: id.generatedAlwaysAsIdentity(),
    timestamp: timestamp.defaultNow(),
  },
  (table) => [index().on(table.timestamp)]
);

/**
 * Used to preserve relations while keep the activites table small and efficient
 * @todo set up a cron job to move old activites to the archive automatically
 */
export const activitiesArchive = pgTable("activities_archive", {
  ...activitiesBaseCols,
  id,
  timestamp,
  archivedAt,
});

import { createInsertSchema, createSelectSchema } from "drizzle-valibot";
import * as v from "valibot";

import { activities } from "@/modules/core/models/activities/schemas";

//// PRIMITIVES ////

const { id } = createSelectSchema(activities).entries;

const { label, failureCause, meta, userId } =
  createInsertSchema(activities).entries;

//// INSERT ////

const insertBaseVariant = {
  label,
  userId: v.nullish(v.unwrap(userId), null),
  meta: v.nullish(v.unwrap(meta), null),
};

export const Insert = v.variant("success", [
  v.object({
    ...insertBaseVariant,
    success: v.literal(true),
    failureCause: v.nullish(v.null(), null),
  }),
  /**
   * You could use another tier of variant schemas keying on the failureCause here.
   * That's how it was originally written, but it became complicated to update/maintain
   **/
  v.object({
    ...insertBaseVariant,
    success: v.literal(false),
    failureCause: v.nonNullish(failureCause),
  }),
]);

//// SELECT ////

export const Select = v.object({ id });

import { eq } from "drizzle-orm";

import { createArchiveFn } from "@/modules/core/helpers/funcs";
import { activities } from "@/modules/core/models/activities/schemas";

import * as queries from "@/modules/core/models/users/queries";
import { users, usersArchive } from "@/modules/core/models/users/schemas";

/** Adds given id to the usersArchive, handles related cascades, and removes it from users */
export const archive = createArchiveFn({
  selectFn: queries.select,
  activeTable: users,
  archiveTable: usersArchive,
  cascades: (tx, id) => [
    tx
      .update(activities)
      .set({ usersArchiveId: id, userId: null })
      .where(eq(activities.userId, id)),
  ],
});

import { eq, getTableColumns, sql } from "drizzle-orm";

import { createQueryFn, createStmtFn } from "@/modules/core/helpers/funcs";

import { users } from "@/modules/core/models/users/schemas";
import * as V from "@/modules/core/models/users/validations";

//// PRIMITIVES ////

const { id } = getTableColumns(users);

//// INSERT ////

const insertStmt = createStmtFn((qx, label) =>
  qx.insert(users).values({}).returning().prepare(`user_insert_${label}`)
);

export const insert = createQueryFn({ vSchema: V.Insert, stmtFn: insertStmt });

//// SELECT ////

const selectStmt = createStmtFn((qx, label) =>
  qx
    .select()
    .from(users)
    .where(eq(id, sql.placeholder("id")))
    .limit(1)
    .prepare(`user_select_${label}`)
);

export const select = createQueryFn({ vSchema: V.Select, stmtFn: selectStmt });

import { pgTable } from "drizzle-orm/pg-core";

import {
  archivedAt,
  createdAt,
  randomId,
  updatedAt,
} from "@/modules/core/helpers/cols";

export const users = pgTable("users", {
  id: randomId.defaultRandom(),
  createdAt: createdAt.defaultNow(),
  updatedAt,
});

export const usersArchive = pgTable("users_archive", {
  id: randomId,
  createdAt,
  updatedAt,
  archivedAt,
});

import { createSelectSchema } from "drizzle-valibot";
import * as v from "valibot";

import { users } from "@/modules/core/models/users/schemas";

//// PRIMITIVES ////

const { id } = createSelectSchema(users).entries;

//// INSERT ////

export const Insert = v.object({});

//// SELECT ////

export const Select = v.object({ id });

import { defineConfig } from "drizzle-kit";

const { DB_URL } = process.env;
if (!DB_URL) throw new Error("Missing db url");

export default defineConfig({
  dialect: "postgresql",
  out: "./db/migrations",
  schema: "./db/models/**/*(schema|view)s.ts",
  dbCredentials: { url: DB_URL },
  casing: "snake_case",
  // Print all statements
  verbose: true,
  // Always ask for confirmation
  strict: true,
});

import { drizzle } from "drizzle-orm/node-postgres";

const { DB_URL } = process.env;
if (!DB_URL) throw new Error("Missing db url");

export const db = drizzle({
  connection: { connectionString: DB_URL },
  casing: "snake_case",
  // logger: true,
});
